    private String taskLabel(JSONObject t){String goal=string(t,"goalStatus"),runtime=t.optString("status");String label;switch(goal){case "active":label="实施中";break;case "paused":label="已暂停";break;case "blocked":label="待处理";break;case "usageLimited":label="用量受限";break;case "budgetLimited":label="预算受限";break;case "complete":label="已完成";break;default:return statusLabel(runtime);}return label+(Arrays.asList("running","waiting","failed").contains(runtime)?" · "+statusLabel(runtime):"");}
