        if(changed){if(!displayedThread.isEmpty())drafts.put(displayedThread,composer.getText().toString());displayedThread=selected;composer.setText(drafts.getOrDefault(selected,""));contentKey="";}if(pendingNavigate.equals(selected))pendingNavigate="";
        displayedTurn=turnId();title.setText(loading?"正在打开会话…":selected.isEmpty()?"新会话":connection.snapshot.optString("activeThreadTitle","会话"));state.setText(online()?"●  工作电脑 · "+statusLabel(connection.snapshot.optString("turnStatus")):"●  "+connection.status);state.setTextColor(online()?PaneUi.GREEN:PaneUi.MUTED);state.setMaxLines(2);modelLabel.setText(modelText()+"  ⌄");modelLabel.setEnabled(online()&&idle()&&!loading);send.setEnabled(online()&&!selected.isEmpty()&&!loading&&pendingText.isEmpty());send.setAlpha(send.isEnabled()?1f:.35f);
        banner.removeAllViews();if(!online()){TextView warning=ui.text(connection.status+"\n未确认发送的草稿会保留，不会自动重发",12,PaneUi.AMBER);ui.pad(warning,20,10);warning.setBackgroundColor(0xfffff2da);banner.addView(warning);warning.setOnClickListener(v->connectionSheet());}
