        if(loading){centered(messages,"正在读取会话历史…",16,PaneUi.MUTED);return;}
        if(items==null||items.length()==0||selected.isEmpty()){ui.gap(messages,55);heroIcon(messages,"chat");ui.gap(messages,24);centered(messages,"开始一段新对话",26,PaneUi.INK);ui.gap(messages,12);centered(messages,"任务将在已连接的电脑上执行",14,PaneUi.MUTED);ui.gap(messages,30);for(String suggestion:new String[]{"检查项目问题","继续编写代码","整理工作记录"}){messages.addView(ui.button(suggestion,Color.WHITE,PaneUi.INK,()->composer.setText(suggestion)));ui.gap(messages,10);}if(selected.isEmpty())messages.addView(ui.primary("新建会话",()->navigate("new")));}
