    private void send(){if(!displayedThread.equals(threadId())||!pendingNavigate.isEmpty()){render();error("会话已切换，请核对输入后发送");return;}String text=composer.getText().toString().trim();if(text.isEmpty())return;if(text.length()>20000){error("消息超过 20000 字符，请分段发送");return;}try{String id=connection.command(NativeConnection.obj("type","turn.send","threadId",displayedThread,"text",text));pendingText.put(id,text);pendingThreads.put(id,displayedThread);composer.setText("");drafts.put(displayedThread,"");send.setEnabled(false);hideKeyboard();}catch(Exception e){error(e.getMessage());}}
    private String command(JSONObject value){try{return connection.command(value);}catch(Exception e){error(e.getMessage());return null;}}
    @Override public void changed(JSONObject event){String type=event.optString("type");
        if("command.result".equals(type)){String id=event.optString("requestId"),text=pendingText.remove(id),destination=pendingThreads.remove(id);boolean ok=event.optBoolean("ok");if(text!=null&&!ok)restoreDraft(destination,text);if(id.equals(pendingNew)){pendingNew="";if(ok){newPrompt="";newDirectory="";if(newText!=null)newText.setText("");if(newCwd!=null)newCwd.setText("");navigate("chat");}else if(createButton!=null)createButton.setText("开始会话");}if(id.equals(pendingFork)){pendingFork="";if(ok)navigate("chat");}if(!ok){pendingNavigate="";error(event.optString("message","操作未完成"));}}
        if("connection".equals(type)&&!connection.authenticated){connection.historyRequest="";boolean uncertain=!pendingText.isEmpty()||!pendingNew.isEmpty()||!pendingFork.isEmpty();for(Map.Entry<String,String> e:pendingText.entrySet())restoreDraft(pendingThreads.get(e.getKey()),e.getValue());pendingText.clear();pendingThreads.clear();pendingNew="";pendingFork="";pendingNavigate="";if(createButton!=null)createButton.setText("开始会话");if(uncertain)Toast.makeText(this,"操作结果尚未确认，输入已保留。请先核对历史，避免重复操作。",Toast.LENGTH_LONG).show();}
        if("chat".equals(route)&&!displayedThread.equals(threadId()))renderChat();if(!scheduled){scheduled=true;handler.postDelayed(()->{scheduled=false;if(!isFinishing()&&connection.visible)render();},100);}
    }
    private void restoreDraft(String destination,String text){if(destination==null)return;String previous=unconfirmed.getOrDefault(destination,"");unconfirmed.put(destination,previous+(previous.isEmpty()?"":"\n\n")+text);}
    private void recoverySheet(){final String destination=displayedThread,text=unconfirmed.get(destination);if(text==null)return;LinearLayout c=ui.column();c.addView(ui.text("先核对会话历史，避免重复发送。当前输入会单独保留。",14,PaneUi.MUTED));ui.gap(c,16);TextView value=ui.text(text,16,PaneUi.INK);value.setTextIsSelectable(true);c.addView(value);ui.gap(c,20);Dialog d=sheet("未确认发送的消息",c);c.addView(ui.primary("复制消息",()->copy(text)));ui.gap(c,10);c.addView(ui.button("已核对，移除此记录",PaneUi.BG,PaneUi.BLUE,()->{if(!text.equals(unconfirmed.get(destination))){d.dismiss();error("未确认消息已更新，请重新查看后核对");return;}unconfirmed.remove(destination);d.dismiss();render();}));}
    private void render(){
        if("verify".equals(route)){title.setText(connection.confirmation.isEmpty()?"······":connection.confirmation);state.setText(connection.confirmation.isEmpty()?connection.status:"等待电脑确认…");if(connection.authenticated&&connection.confirmation.isEmpty()){pairingInProgress=false;navigate("tasks");}return;}
        if("chat".equals(route)){renderChat();return;}if("tasks".equals(route)||"sessions".equals(route)){if("sessions".equals(route)&&online()&&(!connection.historyLoaded||!query.equals(connection.historyQuery))&&connection.historyRequest.isEmpty())loadSessions(true);state.setText(online()?"●  工作电脑 · 已连接":"●  "+connection.status);state.setTextColor(online()?PaneUi.GREEN:PaneUi.MUTED);renderList();}
        if(("settings".equals(route)||"connection".equals(route))&&state!=null){state.setText(online()?"● 已连接 · 已加密":connection.status);state.setTextColor(online()?PaneUi.GREEN:PaneUi.AMBER);}if("new".equals(route)&&createButton!=null)createButton.setEnabled(online()&&pendingNew.isEmpty());
    }
